Federal Old-Age and Survivors Insurance Trust Fund = 1,459.5\n# FY 1950: Appropriations to Federal Old-Age and Survivors Insurance Trust Fund = 2,106.4\n\nstart_value = 1459.5\nend_value = 2106.4\nyears = 3  # From FY 1947 to FY 1950\n\n# CAGR = (End Value / Start Value)^(1/n) - 1\ncagr = (end_value / start_value) ** (1/years) - 1\n\n# Convert to percentage and round to nearest thousandth\ncagr_percent = cagr * 100\nprint(f\"CAGR: {cagr_percent:.3f}% per year\")\n\n# More precision\nprint(f\"More precise: {cagr_percent:.6f}%\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
